class Patient { private String patientName; private int age; private double weight; Patient(String patientName,int age,double weight){this.patientName=patientName;this.age=age;this.weight=weight;} public String getPatientName(){return patientName;} public void setPatientName(String v){patientName=v;} public int getAge(){return age;} public void setAge(int age){if(age>=0)this.age=age;} public double getWeight(){return weight;} public void setWeight(double weight){if(weight>0)this.weight=weight;} void displayPatient(){System.out.println(patientName+" "+age+" "+weight);} }
public class Q07_PatientMain { public static void main(String[] a){Patient p=new Patient("Asha",25,55);p.setAge(-1);p.setWeight(60);p.setWeight(-2);p.displayPatient();} }
